7	
8	/**
9	 * Rejects 409 when the built owner's telephone is already used by any other owner.
10	 * Runs after {@link NormalizeOwnerTelephone}, so the telephone compared here is already E.164;
11	 * existing owners' telephones are converted to E.164 the same way before comparing.
12	 */
13	public class RejectDuplicateOwnerTelephone {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
16	            throws DuplicateOwnerTelephoneException {
17	        String telephone = owner.getTelephone();
18	        for (Owner other : ownerRepository.findAll()) {
19	            if (other != owner && telephone.equals(E164Telephone.toE164(other.getTelephone()))) {
20	                throw new DuplicateOwnerTelephoneException(telephone);
21	            }
22	        }
23	    }
24	}
